from __future__ import annotations

import csv
import importlib.util
import json
import math
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Any

ROOT = Path(r"C:\Users\santi\OneDrive\Escritorio\ALPHA_ENGINE_PRODUCTION")
REC = ROOT / "ALPHA_ENGINE_DATA_RECOVERY_V1"
STATE = ROOT / "public" / "data" / "alpha_product_state.json"
MARKET = REC / "outputs" / "data_recovery_v1" / "live" / "mercado_riesgo_live_latest.csv"
WEB = ROOT / "web"

GROQ_API_KEY = os.environ.get("GROQ_API_KEY", "").strip()
GROQ_MODEL = os.environ.get("GROQ_MODEL", "qwen/qwen3.8-27b").strip()
GROQ_URL = "https://api.groq.com/openai/v1/chat/completions"

spec = importlib.util.spec_from_file_location(
    "alpha_web_base",
    ROOT / "web" / "server.py",
)
if spec is None or spec.loader is None:
    raise RuntimeError("CANNOT_LOAD_BASE_WEB_SERVER")

base = importlib.util.module_from_spec(spec)
spec.loader.exec_module(base)

sys.path.insert(0, str(REC / "src"))
from alpha_data_recovery.yahoo_chart import recover_market


def num(v: Any) -> float | None:
    try:
        x = float(v)
        return x if math.isfinite(x) else None
    except Exception:
        return None


_market_cache_mtime = None
_market_lookup = {}


def load_market_lookup():
    global _market_cache_mtime, _market_lookup
    mtime = MARKET.stat().st_mtime
    if _market_cache_mtime == mtime and _market_lookup:
        return _market_lookup

    with MARKET.open("r", encoding="utf-8-sig", newline="") as fh:
        rows = list(csv.DictReader(fh))

    lookup = {}
    for row in rows:
        canonical = str(row.get("Ticker") or "").strip().upper()
        symbol = str(row.get("Yahoo Symbol") or "").strip().upper()
        if canonical:
            lookup[canonical] = row
        if symbol:
            lookup[symbol] = row

    _market_cache_mtime = mtime
    _market_lookup = lookup
    return lookup


def row_snapshot(requested: str, row: dict) -> dict:
    price = num(row.get("Precio"))
    var = num(row.get("Var 1D"))
    previous = None
    if price is not None and var is not None and (1.0 + var) != 0:
        previous = price / (1.0 + var)

    change = None
    if price is not None and previous is not None:
        change = price - previous

    return base.sanitize({
        "status": "PASS",
        "ticker": requested,
        "symbol": row.get("Yahoo Symbol") or requested,
        "regular_market_price": price,
        "previous_close": previous,
        "change": change,
        "change_pct": var,
        "regular_market_time": row.get("Actualización"),
        "source": row.get("Fuente") or "ALPHA_ENGINE_DATA_RECOVERY_V1",
        "data_authority": "ALPHA_ENGINE_DATA_RECOVERY_V1",
        "var_1d_contract": "price / previous_session_daily_close - 1",
        "include_prepost": False,
        "sparkline": [],
    })


def recovery_snapshot(requested: str) -> dict:
    snap, history = recover_market(requested, requested)
    f = snap.fields
    price = f["price"].value
    previous = f["previous_close"].value
    var = f["var_1d"].value

    if snap.overall_status in {"INVALID", "MISSING", "QUARANTINE"}:
        return base.sanitize({
            "status": snap.overall_status,
            "ticker": requested,
            "symbol": requested,
            "regular_market_price": price,
            "previous_close": previous,
            "change_pct": var,
            "source": f["price"].source,
            "data_authority": "ALPHA_ENGINE_DATA_RECOVERY_V1",
            "include_prepost": False,
            "error": f["price"].detail,
        })

    return base.sanitize({
        "status": "PASS",
        "ticker": requested,
        "symbol": snap.market_symbol,
        "regular_market_price": price,
        "previous_close": previous,
        "change": (
            price - previous
            if price is not None and previous is not None
            else None
        ),
        "change_pct": var,
        "regular_market_time": f["price"].asof,
        "source": f["price"].source,
        "data_authority": "ALPHA_ENGINE_DATA_RECOVERY_V1",
        "var_1d_contract": "price / previous_session_daily_close - 1",
        "include_prepost": False,
        "sparkline": [
            {"time": r.get("timestamp"), "close": r.get("close")}
            for r in history[-60:]
            if r.get("close") is not None
        ],
    })


def audited_market_snapshot(ticker, force=False):
    requested = str(ticker or "").strip().upper()
    if not requested:
        raise ValueError("EMPTY_TICKER")

    row = load_market_lookup().get(requested)
    if row is not None:
        return row_snapshot(requested, row)

    return recovery_snapshot(requested)


def local_only_state(force=False):
    if not STATE.exists():
        raise FileNotFoundError(f"MISSING_PRODUCT_STATE: {STATE}")

    state = json.loads(STATE.read_text(encoding="utf-8"))
    state = base.sanitize(state)

    if state.get("schema") != "ALPHA_ENGINE_PRODUCT_STATE_V1":
        raise RuntimeError("INVALID_PRODUCT_STATE_SCHEMA")
    if (state.get("system") or {}).get("status") != "PASS":
        raise RuntimeError("PRODUCT_STATE_NOT_PASS")

    personal = state.get("personal") or {}
    positions = personal.get("positions") or []
    overview = dict(state.get("overview") or {})
    overview["personal_positions_count"] = int(
        personal.get("positions_count")
        or personal.get("position_rows")
        or len(positions)
        or 0
    )
    overview["personal_operations_count"] = int(
        personal.get("operations_count") or 0
    )
    state["overview"] = overview

    state["_web"] = {
        "source": "LOCAL_DATA_RECOVERY_V1",
        "version": "ALPHA_WEB_V3_1",
        "alpha_configured": bool(GROQ_API_KEY),
        "alpha_provider": "GROQ",
        "alpha_model": GROQ_MODEL,
        "market_source": "ALPHA_ENGINE_DATA_RECOVERY_V1",
        "market_prepost": False,
    }
    return state


def _recent_history(history):
    out = []
    for item in (history or [])[-8:]:
        if not isinstance(item, dict):
            continue
        role = item.get("role")
        content = item.get("content")
        if role in {"user", "assistant"} and isinstance(content, str) and content.strip():
            out.append({
                "role": role,
                "content": content.strip()[:8000],
            })
    return out


def ask_alpha_groq(state, message, history):
    if not GROQ_API_KEY:
        return {
            "status": "NOT_CONFIGURED",
            "answer": (
                "Alpha Decision Desk está listo, pero falta configurar "
                "GROQ_API_KEY en el launcher local."
            ),
            "model": GROQ_MODEL,
            "provider": "GROQ",
        }

    context = base.alpha_context(state, message)

    instructions = """
IDENTIDAD
Sos Alpha, el Decision Desk de Alpha Engine.
No sos una interfaz genérica de chat y nunca te presentes como ChatGPT.
Tu voz es la de un analista cuantitativo institucional integrado al sistema.

JERARQUÍA DE AUTORIDAD
1. V13 IDEAL es la autoridad teórica y cuantitativa del modelo.
2. BYMA es una traducción/implementación local separada; no reemplaza V13.
3. Mercado y fundamentales provienen del Data Recovery auditado.
4. La cartera personal es un ledger/snapshot independiente y nunca contamina V13.
5. No existen órdenes automáticas.

REGLAS DE DATOS
- Nunca inventes un precio, fundamental, target, posición, peso o señal.
- Si un dato no está en el contexto, decí que no está disponible.
- Diferenciá explícitamente dato live, dato de modelo y snapshot personal.
- La cartera personal actual está en modo AUDITED_SNAPSHOT_NOT_LIVE hasta validar BYMA+MEP live.
- No reutilices scores V8/V10.
- Regular session solamente; pre-market y post-market están excluidos.
- Si una pregunta mezcla V13 ideal con la implementación BYMA, separá ambas capas.
- No presentes una interpretación del LLM como cálculo del motor.

ESTILO
- Español claro, profesional y directo.
- Sin emojis.
- Para análisis complejos preferí: SEÑAL / EVIDENCIA / RIESGOS / LECTURA.
- Para preguntas simples respondé directamente.
- Mencioná fuentes/capas internas cuando ayude a auditar la respuesta.
""".strip()

    messages = [{"role": "system", "content": instructions}]
    messages.extend(_recent_history(history))
    messages.append({
        "role": "user",
        "content": (
            "CONTEXTO AUDITADO DE ALPHA ENGINE:\n"
            + json.dumps(
                context,
                ensure_ascii=False,
                separators=(",", ":"),
            )
            + "\n\nCONSULTA:\n"
            + str(message).strip()
        ),
    })

    payload = {
        "model": GROQ_MODEL,
        "messages": messages,
        "temperature": 0.2,
        "reasoning_effort": "medium",
        "reasoning_format": "hidden",
        "max_completion_tokens": 2400,
    }

    req = urllib.request.Request(
        GROQ_URL,
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + GROQ_API_KEY,
            "Content-Type": "application/json",
            "User-Agent": "AlphaEngineDecisionDesk/3.1",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(req, timeout=75) as resp:
            result = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(
            f"GROQ_HTTP_{exc.code}: {body[:1000]}"
        ) from exc

    choices = result.get("choices") or []
    if not choices:
        raise RuntimeError("GROQ_EMPTY_CHOICES")

    answer = (
        ((choices[0] or {}).get("message") or {}).get("content")
        or ""
    ).strip()

    if not answer:
        raise RuntimeError("GROQ_EMPTY_ANSWER")

    return {
        "status": "PASS",
        "answer": answer,
        "model": result.get("model") or GROQ_MODEL,
        "provider": "GROQ",
    }


# -----------------------------------------------------------------
# Runtime overrides only. Original web/server.py remains untouched.
# -----------------------------------------------------------------

base.load_state = local_only_state
base.yahoo_market_snapshot = audited_market_snapshot
base.ask_alpha = ask_alpha_groq

# Original health/main display checks these globals.
base.OPENAI_API_KEY = GROQ_API_KEY
base.OPENAI_MODEL = GROQ_MODEL

_original_serve_index = base.Handler.serve_index
_original_do_get = base.Handler.do_GET


def serve_index_v31(self):
    html = (WEB / "index.html").read_text(encoding="utf-8")
    html = html.replace(
        "</head>",
        '<link rel="stylesheet" href="/finish.css?v=31">\n</head>',
    )
    html = html.replace(
        "</body>",
        '<script src="/finish.js?v=31"></script>\n</body>',
    )

    # Preserve V3 injections from the original server if index.html does not
    # already contain them.
    if "/v3.css" not in html:
        html = html.replace(
            "</head>",
            '<link rel="stylesheet" href="/v3.css?v=3">\n</head>',
        )
    if "/v3.js" not in html:
        html = html.replace(
            "</body>",
            '<script src="/v3.js?v=3"></script>\n</body>',
        )

    self.send_bytes(
        html.encode("utf-8"),
        "text/html; charset=utf-8",
    )


def do_get_v31(self):
    path = urllib.parse.urlparse(self.path).path
    extra = {
        "/finish.css": (WEB / "finish.css", "text/css; charset=utf-8"),
        "/finish.js": (WEB / "finish.js", "application/javascript; charset=utf-8"),
        "/assets/alpha-engine-wordmark.png": (
            WEB / "assets" / "alpha-engine-wordmark.png",
            "image/png",
        ),
    }
    if path in extra:
        target, mime = extra[path]
        if not target.exists():
            self.send_error(404)
            return
        self.send_bytes(target.read_bytes(), mime)
        return
    return _original_do_get(self)


base.Handler.serve_index = serve_index_v31
base.Handler.do_GET = do_get_v31

if __name__ == "__main__":
    base.main()
