(() => {
  "use strict";

  const WORDMARK = "/assets/alpha-engine-wordmark.png?v=31";

  function text(el) {
    return (el && el.textContent ? el.textContent : "").trim();
  }

  function replaceText(root, from, to) {
    const walker = document.createTreeWalker(
      root,
      NodeFilter.SHOW_TEXT
    );
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(node => {
      if (node.nodeValue && node.nodeValue.includes(from)) {
        node.nodeValue = node.nodeValue.replaceAll(from, to);
      }
    });
  }

  function brandPass() {
    const imgs = [...document.querySelectorAll('img')].filter(img => {
      const s = (img.getAttribute("src") || "").toLowerCase();
      return s.includes("alpha-engine-logo") ||
             s.includes("alpha_engine_logo") ||
             s.includes("alpha-engine-wordmark");
    });

    imgs.forEach(img => {
      const parent = img.parentElement;
      const parentText = text(parent).toUpperCase();
      img.src = WORDMARK;
      img.decoding = "async";

      // Sidebar: full horizontal lockup, hide duplicate text next to it.
      if (
        parent &&
        parentText.includes("ALPHA ENGINE") &&
        parentText.includes("MARKET INTELLIGENCE")
      ) {
        parent.classList.add("ae-sidebar-brand-final");
        img.classList.remove("ae-logo-mark");
        img.classList.add("ae-logo-wordmark");

        [...parent.children].forEach(child => {
          if (child !== img && !child.contains(img)) {
            child.style.display = "none";
          }
        });
        return;
      }

      // Compact Decision Desk / badge locations: crop the same asset to its mark.
      const rect = img.getBoundingClientRect();
      if ((rect.width && rect.width <= 90) || (rect.height && rect.height <= 72)) {
        img.classList.remove("ae-logo-wordmark");
        img.classList.add("ae-logo-mark");
      } else {
        img.classList.remove("ae-logo-mark");
        img.classList.add("ae-logo-wordmark");
      }
    });
  }

  async function statePass() {
    try {
      const r = await fetch("/api/state?refresh=1", { cache: "no-store" });
      if (!r.ok) return;
      const s = await r.json();

      const count =
        Number(s?.personal?.positions_count ??
               s?.personal?.position_rows ??
               s?.personal?.positions?.length ??
               0);

      if (count > 0) {
        [...document.querySelectorAll("body *")].forEach(el => {
          if (el.children.length !== 0) return;
          const v = text(el);
          if (/^0 posiciones$/i.test(v)) {
            el.textContent = `${count} posiciones · snapshot auditado`;
          }
        });
      }

      const model = s?._web?.alpha_model;
      const configured = Boolean(s?._web?.alpha_configured);

      replaceText(document.body, "OPENAI_API_KEY", "GROQ_API_KEY");
      replaceText(
        document.body,
        "DISABLED_PENDING_GROQ_QWEN",
        configured && model ? model : "GROQ / QWEN"
      );

      if (configured) {
        [...document.querySelectorAll("body *")].forEach(el => {
          if (el.children.length !== 0) return;
          const v = text(el).toUpperCase();
          if (v === "API KEY") {
            el.textContent = "GROQ / QWEN";
            el.classList.add("ae-v31-chip");
          }
        });
      }
    } catch (_) {
      // Cosmetic layer must never break the product.
    }
  }

  let scheduled = false;
  function run() {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(async () => {
      scheduled = false;
      brandPass();
      await statePass();
    });
  }

  document.addEventListener("DOMContentLoaded", run);
  window.addEventListener("load", run);

  const observer = new MutationObserver(run);
  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });

  setTimeout(run, 500);
  setTimeout(run, 1800);
})();
