)

python -m py_compile $WRAPPER
if ($LASTEXITCODE -ne 0) { throw "Wrapper Python syntax failed." }
python -m py_compile $SMOKE
if ($LASTEXITCODE -ne 0) { throw "Smoke Python syntax failed." }

Write-Host "  PASS wrapper/css/js/logo/launcher"

Write-Host ""
Write-Host "[5/7] RESTART ONLY ALPHA DR1 SERVER"

$listeners = @(
    Get-NetTCPConnection -State Listen -LocalPort 8765 -ErrorAction SilentlyContinue
)

foreach ($listener in $listeners) {
    $pid = $listener.OwningProcess
    $proc = Get-CimInstance Win32_Process -Filter "ProcessId = $pid"
    $cmd = [string]$proc.CommandLine

    if ($cmd -notlike "*run_data_recovery_server.py*") {
        throw "Port 8765 occupied by non-Alpha process PID=$pid. Nothing killed."
    }

    Stop-Process -Id $pid -Force
    Write-Host "  stopped old Alpha server PID=$pid"
}

Start-Sleep -Milliseconds 700

$launcher = Start-Process `
    -FilePath "powershell.exe" `
    -ArgumentList @(
        "-NoProfile",
        "-ExecutionPolicy", "Bypass",
        "-File", $START
    ) `
    -WindowStyle Hidden `
    -PassThru

Write-Host "  launcher PID=$($launcher.Id)"

Write-Host ""
Write-Host "[6/7] FULL HTTP + GROQ/QWEN SMOKE"

Set-Location $ROOT
python $SMOKE
if ($LASTEXITCODE -ne 0) {
    throw "Web V3.1 smoke failed. Review web_runtime.log; V13 remains untouched."
}

